package net.officefloor.hq.app.rate;

import net.officefloor.hq.app.sheet.Sheet;
import org.springframework.format.annotation.DateTimeFormat;
import net.officefloor.hq.app.history.SheetHistory;
import net.officefloor.hq.app.rollup.Rollup;
import jakarta.validation.Valid;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/** Rates on a sheet: each grade's, by from-date. The caller's signed-in name comes in the {@code X-User} header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/rates")
public class RateController {

    /** A grade's rate as the screen shows it: a percent with exactly two decimals, and the day it
     *  takes effect (null when it applies from the beginning of time) and the last day it applies
     *  (null when it does not end), and how many versions it has had (the one shown is the newest). A forward-only
     *  rate has claimsAfter, the highest claim id there was when it was saved: it applies only to claims with a
     *  higher id, a claim up to it taking the newest of the older versions (earlier, newest first) that applies to
     *  it, if any; null when it applies to every claim. */
    public record RateView(String grade, String rate, LocalDate from, LocalDate to, int version, Long claimsAfter,
            List<EarlierRateView> earlier) {

        /** A view kept before rates had versions has none recorded: it was the first; one kept before rates could be
         *  forward-only has no older versions to show. */
        public RateView {
            version = Math.max(version, 1);
            earlier = earlier == null ? List.of() : earlier;
        }

        public static RateView of(Rate rate) {
            return new RateView(rate.getGrade(), rate.getRate().toPlainString(), rate.getFromDate(),
                    rate.getToDate(), rate.getVersion(), rate.getClaimsAfter(),
                    rate.getEarlier().stream().map(EarlierRateView::of).toList());
        }
    }

    /** An older version of a forward-only rate a claim it does not apply to may take: its percent (two decimals), its
     *  to-date (null when it does not end) and, when it was forward-only too, the highest claim id when it was saved. */
    public record EarlierRateView(String rate, LocalDate to, Long claimsAfter) {

        static EarlierRateView of(RateVersion version) {
            return new EarlierRateView(version.getRate().toPlainString(), version.getToDate(),
                    version.getClaimsAfter());
        }
    }

    /** A rate as the form submits it: a percent of 0.00 or more with up to two decimals, and an
     *  optional from-date and to-date. */
    public record RateForm(@NotNull @DecimalMin("0.00") @Digits(integer = 7, fraction = 2) BigDecimal rate,
            LocalDate from, LocalDate to) {
    }

    private final RateService rates;
    private final SheetHistory history;

    public RateController(RateService rates, SheetHistory history) {
        this.history = history;
        this.rates = rates;
    }

    /** What a candidate rate for a grade, applied on every date, would change; nothing is saved. */
    @GetMapping("/{grade}/preview")
    public Rollup.RatePreview preview(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable @Pattern(regexp = Sheet.GRADE_CODE) String grade,
            @RequestParam @NotNull @DecimalMin("0.00") @Digits(integer = 7, fraction = 2) BigDecimal rate) {
        return rates.preview(sheetId, grade, rate);
    }

    @GetMapping
    public List<RateView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(value = SheetHistory.AS_OF_HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        if (asOf != null) {
            return history.viewsAsOf(sheetId, asOf).rates();
        }
        return rates.list(sheetId).stream().map(RateView::of).toList();
    }

    /** The rates of the sheet's ancestors, nearest first (its parent's, its parent's parent's, up to three levels
     *  up, then the line of the sheet it was cloned from), each by grade in the order they take effect: a grade with
     *  no rate in force on a date on the sheet takes the first in force on that date up the line. As of a date, each as it stood then. */
    @GetMapping("/inherited")
    public List<List<RateView>> inherited(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(value = SheetHistory.AS_OF_HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        if (asOf != null) {
            return history.inheritedAsOf(sheetId, asOf);
        }
        return rates.ancestorsOf(sheetId).stream()
                .map(ancestor -> rates.list(ancestor).stream().map(RateView::of).toList())
                .toList();
    }

    @PutMapping("/{grade}")
    public RateView set(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable @Pattern(regexp = Sheet.GRADE_CODE) String grade,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody RateForm request) {
        return RateView.of(rates.set(sheetId, user, grade, request.from(), request.to(), request.rate()));
    }
}
package net.officefloor.hq.app.rate;

import net.officefloor.hq.app.sheet.Sheet;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The rate set for each grade on a sheet. */
@Service
public class RateService {

    private final RateRepository rates;
    private final SheetService sheets;
    private final Audit audit;
    private final Rollup rollup;
    private final RateChains chains;
    private final RateVersionRepository versions;
    private final ClaimRepository claims;

    public RateService(RateRepository rates, SheetService sheets, Audit audit, Rollup rollup, RateChains chains,
            RateVersionRepository versions, ClaimRepository claims) {
        this.claims = claims;
        this.versions = versions;
        this.chains = chains;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
        this.rollup = rollup;
    }

    /** The rates set on the sheet, by grade, each grade's in the order they take effect. */
    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return chains.ratesOf(sheetId).stream()
                .sorted(Comparator.comparing(Rate::getGrade).thenComparing(Rate.BY_FROM))
                .toList();
    }

    /** The ids of the sheet's ancestors whose rates stand in for its own, nearest first. */
    @Transactional(readOnly = true)
    public List<String> ancestorsOf(String sheetId) {
        return chains.ancestorsOf(sheetId);
    }

    /** What a candidate rate for a grade would change were it to apply on every date; nothing is stored. */
    @Transactional(readOnly = true)
    public Rollup.RatePreview preview(String sheetId, String grade, BigDecimal rate) {
        return rollup.preview(sheetId, grade, rate);
    }

    /** Set a grade's rate from a date (null: from the beginning of time) through a to-date (null: it
     *  does not end). When the grade already has a rate from that same date, the value it replaces is
     *  kept as an older version and the new one becomes the newest version, the one in force. A to-date
     *  before the from-date is refused. A rate from a date on or after the sheet's today is forward-only: it applies
     *  only to claims added after it is saved, and a claim already there keeps the rate that applied to it (the
     *  version it replaces included); any other applies to every claim. */
    @Transactional
    public Rate set(String sheetId, String user, String grade, LocalDate from, LocalDate to, BigDecimal rate) {
        if (from != null && to != null && to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A rate cannot end before it starts");
        }
        Sheet sheet = sheets.load(sheetId, user);
        SheetService.requireGrade(sheet, grade);
        LocalDate today = sheet.getToday();
        Long claimsAfter = from != null && !from.isBefore(today) ? claims.lastId() : null;
        BigDecimal scaled = rate.setScale(2, RoundingMode.UNNECESSARY);
        Rollup.Figures before = rollup.of(sheetId);
        Rate row = rates.findBySheetIdAndGrade(sheetId, grade).stream()
                .filter(r -> Objects.equals(r.getFromDate(), from))
                .findFirst()
                .orElse(null);
        if (row == null) {
            row = new Rate(sheetId, grade, from, scaled);
        } else {
            versions.save(new RateVersion(row.getId(), row.getVersion(), row.getRate(), row.getToDate(),
                    row.getClaimsAfter()));
            row.setVersion(row.getVersion() + 1);
        }
        row.setRate(scaled);
        row.setToDate(to);
        row.setClaimsAfter(claimsAfter);
        Rate saved = chains.withEarlier(List.of(rates.saveAndFlush(row))).get(0);
        audit.recordChangeOnCommit(sheetId, user, "RATE_SET sheet=" + sheetId + " by=" + user
                + " grade=" + saved.getGrade() + " rate=" + saved.getRate().toPlainString()
                + (from == null ? "" : " from=" + from)
                + (to == null ? "" : " to=" + to));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }
}

